            $("#category_select").change(function() {
                var domain  = $('#domain').val()
                var catg    = $('#category_select').val()
                var options = _getCagegoryTestMap()[domain][catg]

                slct_elem   = _SelectElementsMap()['tests']
                $('#'+slct_elem).empty()
                var opt = new Option(" -- select an option -- ", "")
                $('#'+slct_elem).append(opt)
                 
                options.forEach( option_text=>{
                    $('#'+slct_elem).append(new Option(option_text, option_text))
                })
            });

            function _addDomainSelects(){
                var slct_elem = "domain"
                $('#'+slct_elem).empty()
                var opt = new Option(" -- select an option -- ", "")
                $('#'+slct_elem).append(opt)
                domains.forEach( option_text=>{
                    $('#'+slct_elem).append(new Option(option_text, option_text))
                })
                opt.disabled = true
            };

            function _addSelectOptions(domain){
                if ( Object.keys(_getOptionsMap() ).includes(domain) ){
                    var optionsDict    = _getOptionsMap()[domain] 

                    Object.keys(_SelectElementsMap() ).forEach( item =>{
                           if ( Object.keys(optionsDict).includes(item) ){
                               var options   = optionsDict[item]
                               var slct_elem = _SelectElementsMap()[item]
                            $('#'+slct_elem).empty()
                     
                            $('#'+slct_elem).append(new Option(" -- select an option -- ", ""))
                             
                               options.forEach( option_text=>{
                                $('#'+slct_elem).append(new Option(option_text, option_text))
                            })
                           }
                       })
                    
                }
            };

            function _getValidElms(domain){
                validItems = _getValidItems(domain)
                validElems = []
                for(i=0; i<validItems.length; i++){
                    validElems.push(  _getQueryDisplayElements(validItems[i])  )
                }
                return validElems
            };
            function _hideAllElms(){
                allElms = $.map( _classElementsMap(), function(value,key){return value});
                for(i=0; i< allElms.length; i++){
                    $('#'+allElms[i]).hide()
                }
            };
            function addTest(element){
                var queryName = "queryArea1";
                var testCollectionNanme = "TestCollection";
                var testDiv = "Test";
                var $div = $('#' + queryName + ' .' + testCollectionNanme + ' div[class^="' + testDiv + '"]:last');

                var num = parseInt($div.prop("class").match(/\d+/g), 10) + 1;

                var $query = $div.clone().prop('class', testDiv + num);

                $('#' + queryName + ' .' + testCollectionNanme).append($query)

                $('#' + queryName + ' .' + testCollectionNanme + ' div[class^="' + testDiv + '"]:last button').click(function () {
                    $('#' + queryName + ' .' + testCollectionNanme + ' .' + testDiv + num).remove();
                });
            };
            
