            function fetchData(element){
                var $button=element;
                var queryName = "queryArea1";
                var studies = $('#studies').val();
                var productClasses = $('#productClasses').val();
                var rescaleOptions = $("#"+queryName+' #rescaleOptions select').val();
                var rescaleType = $("#"+queryName+' #rescaleTypes select').val();
                var convertType = $("#"+queryName+' #convert select').val();
                var queryObject=query_definitions;
                var queryType=$("#" + queryName + " #queryType1").val();
                var querySummary={};

                
                if(queryType=='summary'){
                    querySummary["query_type"]="PATIENT_LEVEL";
                    delete queryObject["INTERP_FUNCTION"];
                }else{
                    querySummary["query_type"]="TIME_SERIES";
                    delete queryObject["AGG_FUNCTION"];
                }

                for(var property in queryObject){
                    var configlist=[];
                    for(var id in queryObject[property]){
                        var query_element=queryObject[property][id];
                        configlist.push(query_element)
                    }
                    if(configlist.length>0){
                        querySummary[property]=configlist;
                    }
                }

                var timeBinStart=$('#queryArea1 .binStart').val();
                var timeBinEnd=$('#queryArea1 .binEnd').val();

                querySummary["global_filters"]=[];
                if (studies == null || studies.length == 0) {
                    querySummary["global_filters"].push({
                        "col": "STUDYID",
                        "condition": "isin",
                        "value": productToID[productClasses]
                    });
                } else {
                    querySummary["global_filters"].push({
                        "col": "STUDYID",
                        "condition": "isin",
                        "value": studies
                    });
                }

                if(queryType!='summary'){
                    querySummary["global_filters"].push({
                        "col": "TS_DATE_RANGE",
                        "condition": "between",
                        "value": [timeBinStart, timeBinEnd]
                    });
                    delete queryObject["INTERP_FUNCTION"];
                }
                
                queryJson = JSON.stringify(querySummary);
                queryJsonPrint = JSON.stringify(querySummary, null, 4);
                getData(element , queryType);
            }
            
